<?php
declare(strict_types=1);
require dirname(__DIR__).'/vendor/autoload.php';
use EdFund\{Config,Database,ContentImport,PostsImport,Posts,Media,YouTube,RichText,ContentConflict};
$c=Config::load();$db=Database::connect($c['db']);if(!preg_match('/\Aedfund_test_[a-f0-9]{12}\z/',$db->query('SELECT DATABASE()')->fetchColumn())){throw new RuntimeException('Isolated fixture required');}
function ok(bool $v,string $m):void{if(!$v){throw new RuntimeException($m);}echo 'PASS '.$m.PHP_EOL;}
function denied(callable $f,string $m):void{try{$f();throw new RuntimeException('Accepted '.$m);}catch(InvalidArgumentException $e){ok(true,$m);}}
(new ContentImport($db))->run();$import=new PostsImport($db,$c);ok($import->run()===3 && $import->run()===0,'current three stories import exactly once');(new Media($db,$c))->indexExisting();
foreach(['https://youtu.be/SexHEvWnk2w?t=17','https://www.youtube.com/watch?v=SexHEvWnk2w','https://www.youtube.com/shorts/SexHEvWnk2w','https://www.youtube-nocookie.com/embed/SexHEvWnk2w'] as $url){ok(YouTube::id($url)==='SexHEvWnk2w','YouTube URL normalized to ID');}
foreach(['https://youtube.com.evil.invalid/watch?v=SexHEvWnk2w','http://youtu.be/SexHEvWnk2w','https://u@youtube.com/watch?v=SexHEvWnk2w','https://youtube.com:444/watch?v=SexHEvWnk2w','<iframe src="https://youtube.com"></iframe>','https://youtu.be/../../private','https://example.org/'] as $url){denied(fn()=>YouTube::id($url,false),'unsafe YouTube input refused');}
$delta=['ops'=>[['insert'=>'<script>alert(1)</script> & text','attributes'=>['bold'=>true]],['insert'=>"\n"],['insert'=>'Heading'],['insert'=>"\n",'attributes'=>['header'=>2]],['insert'=>'Item'],['insert'=>"\n",'attributes'=>['list'=>'bullet']]]];$html=RichText::html($delta);ok(str_contains($html,'&lt;script&gt;')&&!str_contains($html,'<script>')&&str_contains($html,'<strong>')&&str_contains($html,'<h2>Heading</h2>')&&str_contains($html,'<ul>'),'structured rich text escapes content and renders basic formats');
foreach([['ops'=>[['insert'=>['image'=>'javascript:alert(1)']]]],['ops'=>[['insert'=>'x','attributes'=>['style'=>'color:red']],['insert'=>"\n"]]],['ops'=>[['insert'=>'x','attributes'=>['link'=>'javascript:alert(1)']],['insert'=>"\n"]]]] as $bad){denied(fn()=>RichText::validate($bad),'unsupported embed, format or script link refused');}
$posts=new Posts($db,$c);$owner=(int)$db->query('SELECT id FROM cms_users LIMIT 1')->fetchColumn();$new=$posts->create($owner,'Fixture Author');$data=$new['content'];$data['title']='Secure story & opportunity';$data['excerpt']='A real story excerpt.';$data['slug']='phase3-secure-story';$data['featured_image']=$db->query('SELECT id FROM cms_media LIMIT 1')->fetchColumn();$data['featured_alt']='A school picture';$data['blocks']=[['type'=>'text','delta'=>$delta]];
$saved=$posts->change($new['id'],$new['version'],'save',$data,null,$owner);ok($posts->row($new['id'])['published_id']===null,'saved post draft remains unpublished');
try{$posts->change($new['id'],$new['version'],'save',$data,null,$owner);throw new RuntimeException('Stale write');}catch(ContentConflict $e){ok(true,'post concurrent edit conflict');}
$pub=$posts->change($new['id'],$saved['version'],'publish',$data,null,$owner);ok($pub['published']===$pub['draft']&&$pub['content']['published_at']!=='','post publishes with recorded actual date');
$data=$pub['content'];$data['slug']='phase3-renamed-story';denied(fn()=>$posts->change($new['id'],$pub['version'],'publish',$data,null,$owner),'slug change requires explicit confirmation');$renamed=$posts->change($new['id'],$pub['version'],'publish',$data,null,$owner,true);ok($posts->route('phase3-secure-story')['published_slug']==='phase3-renamed-story','old route preserved for a direct redirect');
$restored=$posts->change($new['id'],$renamed['version'],'restore',null,$saved['draft'],$owner);ok($restored['published']===$renamed['published'] && $restored['content']['slug']==='phase3-secure-story','post revision restores as private draft');
$trash=$posts->change($new['id'],$restored['version'],'trash',null,null,$owner);$untrash=$posts->change($new['id'],$trash['version'],'untrash',null,null,$owner);ok(!$untrash['published']&&!$untrash['trashed'],'trash restoration requires explicit republishing');
$counts=$db->query('SELECT COUNT(*) FROM cms_post_revisions')->fetchColumn();ok($import->run()===0 && $db->query('SELECT COUNT(*) FROM cms_post_revisions')->fetchColumn()===$counts,'repeated import preserves all client post revisions');
